with recent_accounts as (select *, trim(account_type) as clean_account_type from accounts where customer_id is null and customer_id in (8, 15, 20, 38) and month(opened_date) in (3, 7, 8)), agg as (select status, min(balance) as min_balance, count(*) as total_count from recent_accounts group by status) select status, min_balance, total_count from agg order by min_balance desc, status limit 10
